def test_setup_generates_local_dev_config_without_secret_output(tmp_path: Path) -> None:
    config_path = tmp_path / "ask.config.yml"

    result = runner.invoke(
        app,
        ["setup", "--profile", "local-dev", "--yes", "--json", "--path", str(config_path)],
    )

    assert result.exit_code == 0, result.output
    payload = json.loads(result.output)
    assert contains_secret_literal(result.output) is False
    assert payload["profile"] == "local-dev"
    assert payload["actions"] == []

    config = yaml.safe_load(config_path.read_text(encoding="utf-8"))
    assert config["setup"]["deployment_profile"] == "local-dev"
    assert config["setup"]["start_missing_services"] is False


def test_shared_stack_profile_does_not_generate_docker_start_actions() -> None:
    config = build_setup_config(profile="shared-stack", provider_credentials="not-required")
    env_template = build_env_template(profile="shared-stack")

    assert config["setup"]["deployment_profile"] == "shared-stack"
    assert config["setup"]["start_missing_services"] is False
    assert config["release"]["require_oauth_credentials"] is False
    assert env_template["MEMORY_BASE_URL"] == ""
    assert env_template["SCILLM_BASE_URL"] == ""
    assert contains_secret_literal(yaml.safe_dump(config)) is False


def test_local_env_template_uses_local_service_urls_without_secrets() -> None:
    env_template = build_env_template(profile="local-dev")

    assert env_template["MEMORY_BASE_URL"] == "http://127.0.0.1:8765"
    assert env_template["SCILLM_BASE_URL"] == "http://127.0.0.1:4001"
    assert env_template["QDRANT_URL"] == "http://127.0.0.1:6333"
    assert env_template["ARANGO_URL"] == "http://127.0.0.1:8529"
    assert contains_secret_literal("\n".join(f"{key}={value}" for key, value in env_template.items())) is False
